CREATE TABLE geo_distribution_epoch(organization_id TEXT PRIMARY KEY REFERENCES organization(id),epoch INTEGER NOT NULL DEFAULT 0 CHECK(epoch>=0));
INSERT INTO geo_distribution_epoch(organization_id) SELECT id FROM organization;
CREATE TRIGGER geo_distribution_new_org AFTER INSERT ON organization BEGIN INSERT INTO geo_distribution_epoch(organization_id) VALUES(NEW.id); END;
CREATE TABLE geo_distribution_run(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL REFERENCES organization(id),dataset_id TEXT NOT NULL,area_id TEXT NOT NULL,effective_from_date TEXT NOT NULL,reason TEXT NOT NULL,preview_hash TEXT NOT NULL,basis_epoch INTEGER NOT NULL,input_json TEXT NOT NULL,result_json TEXT NOT NULL,created_by TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(organization_id,id),FOREIGN KEY(organization_id,dataset_id) REFERENCES admin_boundary_dataset(organization_id,id),FOREIGN KEY(organization_id,area_id) REFERENCES area(organization_id,id),FOREIGN KEY(organization_id,created_by) REFERENCES app_user(organization_id,id));
CREATE INDEX geo_distribution_history ON geo_distribution_run(organization_id,created_at,id);
CREATE TRIGGER geo_distribution_run_immutable BEFORE UPDATE ON geo_distribution_run BEGIN SELECT RAISE(ABORT,'DISTRIBUTION_HISTORY_IMMUTABLE'); END;
CREATE TRIGGER geo_distribution_run_no_delete BEFORE DELETE ON geo_distribution_run BEGIN SELECT RAISE(ABORT,'DISTRIBUTION_HISTORY_IMMUTABLE'); END;
CREATE TRIGGER area_admin_no_delete BEFORE DELETE ON area_admin_membership BEGIN SELECT RAISE(ABORT,'ADMIN_AREA_HISTORY_IMMUTABLE'); END;
CREATE TRIGGER area_admin_reason_immutable BEFORE UPDATE ON area_admin_membership WHEN NEW.id IS NOT OLD.id OR NEW.reason IS NOT OLD.reason BEGIN SELECT RAISE(ABORT,'ADMIN_AREA_HISTORY_IMMUTABLE'); END;
CREATE TRIGGER area_admin_area_active BEFORE INSERT ON area_admin_membership WHEN NOT EXISTS(SELECT 1 FROM area WHERE organization_id=NEW.organization_id AND id=NEW.area_id AND status='active') BEGIN SELECT RAISE(ABORT,'ADMIN_AREA_INACTIVE'); END;
CREATE TRIGGER area_admin_archive_guard BEFORE UPDATE OF status ON area WHEN NEW.status='archived' BEGIN SELECT CASE WHEN EXISTS(SELECT 1 FROM area_admin_membership WHERE organization_id=NEW.organization_id AND area_id=NEW.id AND (effective_to_date IS NULL OR effective_to_date>date('now'))) THEN RAISE(ABORT,'AREA_HAS_GEOGRAPHY_MEMBERSHIP') END; END;
CREATE TRIGGER geo_epoch_area_insert AFTER INSERT ON area BEGIN INSERT INTO geo_distribution_epoch(organization_id,epoch) VALUES(NEW.organization_id,1) ON CONFLICT(organization_id) DO UPDATE SET epoch=epoch+1; END;
CREATE TRIGGER geo_epoch_area_update AFTER UPDATE ON area BEGIN INSERT INTO geo_distribution_epoch(organization_id,epoch) VALUES(NEW.organization_id,1) ON CONFLICT(organization_id) DO UPDATE SET epoch=epoch+1; END;
CREATE TRIGGER geo_epoch_area_delete AFTER DELETE ON area BEGIN INSERT INTO geo_distribution_epoch(organization_id,epoch) VALUES(OLD.organization_id,1) ON CONFLICT(organization_id) DO UPDATE SET epoch=epoch+1; END;
